import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int mod = scanner.nextInt();

        long total = (long) n * (n - 1) / 2;
        long max_idx = (long) n * (n - 1);
        long[][] dp_table = new long[n + 1][(int) max_idx + 1];
        long[][] dp1_table = new long[n + 1][(int) max_idx + 1];

        dp_table[1][(int) total] = 1;

        for (int i = 2; i <= n; i++) {
            long lower_bound = total - (long)(i - 1) * (i - 2) / 2;
            long upper_bound = total + (long)(i - 1) * (i - 2) / 2;
            for (long x = lower_bound; x <= upper_bound; x++) {
                int x_idx = (int) x;
                for (int diff = -i + 1; diff < i; diff++) {
                    int idx = x_idx + diff;
                    if (0 <= idx && idx <= (int) max_idx) {
                        dp_table[i][idx] = (dp_table[i][idx] + dp_table[i - 1][x_idx] * (i - Math.abs(diff))) % mod;
                    }
                }
            }
        }

        for (int i = 2; i <= n; i++) {
            long lower_bound = total - (long)(i - 1) * (i - 2) / 2;
            long upper_bound = total + (long)(i - 1) * (i - 2) / 2;
            for (long x = lower_bound; x <= upper_bound; x++) {
                int x_idx = (int) x;
                dp1_table[i][x_idx] = (dp1_table[i - 1][x_idx] * i) % mod;
            }
            for (long x = lower_bound; x <= upper_bound; x++) {
                int x_idx = (int) x;
                for (int d = 1; d < i; d++) {
                    int idx = x_idx - d;
                    if (0 <= idx && idx <= (int) max_idx) {
                        dp1_table[i][idx] = (dp1_table[i][idx] + dp_table[i - 1][x_idx] * (i - d)) % mod;
                    }
                }
            }
        }

        long result = 0;
        for (int i = 0; i < (int) max_idx + 1; i++) {
            if (i > (int) total) {
                result = (result + dp1_table[n][i]) % mod;
            }
        }
        System.out.println(result);
        scanner.close();
    }
}
